<script setup lang="ts">
import {ref,watch} from 'vue'
import {moduleRequest,cardApi} from './api'
import {useCardText} from './text'
import {cents,displayName} from './format'
import type {Product} from './types'
const props=defineProps<{store:string;disabled:boolean}>(),emit=defineEmits<{saved:[];error:[message:string]}>(),{t,locale}=useCardText(),products=ref<Product[]>([]),busy=ref(false)
const form=ref({nameZh:'',nameEn:'',kind:'stamp',productId:'',total:'30',dailyLimit:'1',validDays:30,stampTarget:10,repeatable:true,rewardDays:7,price:'200.00',taxMode:'inclusive',taxRate:'0'})
watch(()=>props.store,async store=>{products.value=[];try{const rows=await moduleRequest<Product[]>(`/api/v1/stores/${store}/catalog`,'/products');if(store===props.store)products.value=rows.filter(p=>p.status==='active'&&p.channels.includes('cards'))}catch(e){emit('error',String(e))}},{immediate:true})
async function save(){busy.value=true;try{await cardApi(props.store).command('/plans',{...form.value,total:form.value.kind==='stamp'?null:form.value.total?Number(form.value.total):null,dailyLimit:form.value.dailyLimit?Number(form.value.dailyLimit):null,stampTarget:form.value.kind==='stamp'?form.value.stampTarget:0,priceCents:form.value.kind==='stamp'?0:cents(form.value.price)},'plan.create');emit('saved')}catch(e){emit('error',String(e))}finally{busy.value=false}}
</script>
<template><form class="cards-panel" @submit.prevent="save"><h2>{{t('create')}} · {{t('plans')}}</h2><div class="cards-grid"><label>{{t('nameZh')}}<input v-model="form.nameZh"></label><label>{{t('nameEn')}}<input v-model="form.nameEn"></label><label>{{t('kind')}}<select v-model="form.kind"><option v-for="k in ['stamp','count','period']" :key="k" :value="k">{{t(k)}}</option></select></label><label>{{t('product')}}<select v-model="form.productId" required><option value="">{{t('select')}}</option><option v-for="p in products" :key="p.id" :value="p.id">{{displayName(p,locale)}} / {{p.unit}}</option></select></label><label v-if="form.kind!=='stamp'">{{t('total')}}<input v-model="form.total" type="number" min="1" max="1000000" :required="form.kind==='count'"></label><label>{{t('daily')}}<input v-model="form.dailyLimit" type="number" min="1" max="1000000" :required="form.kind==='period'"></label><label>{{t('days')}}<input v-model.number="form.validDays" type="number" min="1" max="3660" required></label><template v-if="form.kind==='stamp'"><label>{{t('target')}}<input v-model.number="form.stampTarget" type="number" min="1" required></label><label>{{t('rewardDays')}}<input v-model.number="form.rewardDays" type="number" min="1" max="3660" required></label><label class="check"><input v-model="form.repeatable" type="checkbox">{{t('repeat')}}</label></template><template v-else><label>{{t('price')}}<input v-model="form.price" inputmode="decimal" required></label><label>{{t('inclusive')}} / {{t('exclusive')}}<select v-model="form.taxMode"><option value="inclusive">{{t('inclusive')}}</option><option value="exclusive">{{t('exclusive')}}</option></select></label><label>{{t('taxRate')}}<input v-model="form.taxRate" inputmode="decimal" required></label></template></div><p class="cards-notice">{{t('dailyHint')}}</p><button class="primary" :disabled="disabled||busy">{{t('save')}}</button></form></template>
